// FUNCTION: BFME2 0x004311A7 size=154 name=?doAttackMoveCommand@@YAHPAXPAUICoord2D@@@Z evidence=N:ledger tier=B hypothesis:K
int doAttackMoveCommand(void *command, ICoord2D *mouse)
{
	// sanity
	if (command == 0 || mouse == 0)
		return 1;

	Drawable *draw = TheInGameUI->getFirstSelectedDrawable();

	// sanity
	if (draw == 0 || draw->getObject() == 0)
		return 1;

	// convert mouse point to world coords
	Coord3D world;
	TheTacticalView->screenToTerrain(mouse, &world, false);

	// send the message to attack move
	GameMessage *msg = TheMessageStream->appendMessage(GameMessage::MSG_DO_ATTACKMOVETO);
	msg->appendLocationArgument(world);

	// Play the unit voice response
	PickAndPlayInfo info;
	info.m_position = world;
	pickAndPlayUnitVoiceResponse(TheInGameUI->getAllSelectedDrawables(), GameMessage::MSG_DO_ATTACKMOVETO, &info);

	return 1;
}

// FUNCTION: BFME2 0x00431241 size=164 name=?doSetRallyPointCommand@@YAHPAXPAUICoord2D@@@Z evidence=N:ledger tier=B hypothesis:K
int doSetRallyPointCommand(void *command, ICoord2D *mouse)
{
	// sanity
	if (command == 0 || mouse == 0)
		return 1;

	// we can only set rally points for structures ... and we never multiple select structures
	Drawable *draw = TheInGameUI->getFirstSelectedDrawable();

	// sanity
	if (draw == 0 || draw->getObject() == 0)
		return 1;

	// convert mouse point to world coords
	Coord3D world;
	TheTacticalView->screenToTerrain(mouse, &world, false);

	// send the message to set the rally point
	GameMessage *msg = TheMessageStream->appendMessage(GameMessage::MSG_SET_RALLY_POINT);
	msg->appendObjectIDArgument(draw->getObject()->getID());
	msg->appendLocationArgument(world);
	bool active = TheKeyboard->isShift();
	msg->appendBooleanArgument(active);
	msg->appendObjectIDArgument(INVALID_ID);

	return 1;
}

// FUNCTION: BFME2 0x004312E5 size=72 name=?Rva004312E5Emit@@YAHPAXPAUICoord2D@@@Z evidence=?:placeholder tier=B hypothesis:K
int doPlaceBeacon(void *command, ICoord2D *mouse)
{
	// sanity
	if (command == 0 || mouse == 0)
		return 1;

	// convert mouse point to world coords
	Coord3D world;
	TheTacticalView->screenToTerrain(mouse, &world, false);

	// send the message to place the beacon
	GameMessage *msg = TheMessageStream->appendMessage(GameMessage::MSG_PLACE_BEACON);
	msg->appendLocationArgument(world);

	return 1;
}

